/**
 * CLIF logo for the letterhead of generated letters of collaboration, as PNG
 * bytes. Embedded here because a serverless function cannot read public/ at
 * runtime. Source: public/images/logos/clif_logo_transparent_FINAL_cropped.png
 */
export const LETTERHEAD_LOGO_WIDTH = 2417;
export const LETTERHEAD_LOGO_HEIGHT = 729;

const LOGO_BASE64 =
  '';

export function letterheadLogoPng(): Uint8Array {
  return Uint8Array.from(Buffer.from(LOGO_BASE64, 'base64'));
}
